CREATE TYPE "SessionStatus" AS ENUM ('CREATED','INTENT_PARSED','INTENT_CONFIRMED','CATALOG_READY','PRODUCT_SELECTED','REVIEW_PENDING','APPROVED','PERMIT_ISSUED','ORDER_CREATED','PAYMENT_VERIFIED','BLOCKED','CANCELLED');
CREATE TYPE "IntentStatus" AS ENUM ('PARSED','CONFIRMED','SUPERSEDED');
CREATE TYPE "EvaluationDecision" AS ENUM ('APPROVE','REVIEW','BLOCK','APPROVE_WITH_OVERRIDE');
CREATE TYPE "PermitStatus" AS ENUM ('ISSUED','RESERVED','USED','EXPIRED','BLOCKED','REVOKED');
CREATE TYPE "PaymentStatus" AS ENUM ('CREATING','ORDER_CREATED','ORDER_FAILED','AUTHENTICATED','CAPTURED','FAILED');
CREATE TABLE "User" ("id" text PRIMARY KEY,"email" text NOT NULL UNIQUE,"displayName" text NOT NULL,"passwordHash" text NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "ShoppingSession" ("id" text PRIMARY KEY,"userId" text NOT NULL REFERENCES "User"("id"),"scenarioId" text NOT NULL,"status" "SessionStatus" NOT NULL DEFAULT 'CREATED',"aiMode" text NOT NULL DEFAULT 'fixture',"paymentMode" text NOT NULL DEFAULT 'mock',"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "UserIntent" ("id" text PRIMARY KEY,"sessionId" text NOT NULL REFERENCES "ShoppingSession"("id") ON DELETE CASCADE,"version" integer NOT NULL,"rawPrompt" text NOT NULL,"rulesJson" jsonb NOT NULL,"status" "IntentStatus" NOT NULL DEFAULT 'PARSED',"intentHash" text NOT NULL,"confirmedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("sessionId","version"));
CREATE TABLE "Product" ("id" text PRIMARY KEY,"catalogId" text NOT NULL,"catalogVersion" text NOT NULL,"merchant" text NOT NULL,"sku" text NOT NULL,"dataJson" jsonb NOT NULL,"active" boolean NOT NULL DEFAULT true,UNIQUE("catalogVersion","sku"));
CREATE TABLE "OfferSet" ("id" text PRIMARY KEY,"sessionId" text NOT NULL REFERENCES "ShoppingSession"("id") ON DELETE CASCADE,"catalogVersion" text NOT NULL,"offerSetHash" text NOT NULL,"offersJson" jsonb NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "AgentDecision" ("id" text PRIMARY KEY,"sessionId" text NOT NULL REFERENCES "ShoppingSession"("id") ON DELETE CASCADE,"mode" text NOT NULL,"selectedProductId" text NOT NULL,"decisionJson" jsonb NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "ChoiceProofEvaluation" ("id" text PRIMARY KEY,"sessionId" text NOT NULL REFERENCES "ShoppingSession"("id") ON DELETE CASCADE,"selectedProductId" text NOT NULL,"decision" "EvaluationDecision" NOT NULL,"evaluationJson" jsonb NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "ExecutionPermit" ("id" text PRIMARY KEY,"sessionId" text NOT NULL REFERENCES "ShoppingSession"("id") ON DELETE CASCADE,"evaluationId" text NOT NULL REFERENCES "ChoiceProofEvaluation"("id"),"cartJson" jsonb NOT NULL,"cartHash" text NOT NULL,"signature" text NOT NULL,"nonce" text NOT NULL,"expiresAt" timestamptz NOT NULL,"status" "PermitStatus" NOT NULL DEFAULT 'ISSUED',"reservedAt" timestamptz,"usedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "Payment" ("id" text PRIMARY KEY,"sessionId" text NOT NULL REFERENCES "ShoppingSession"("id") ON DELETE CASCADE,"permitId" text NOT NULL REFERENCES "ExecutionPermit"("id"),"idempotencyKey" text NOT NULL UNIQUE,"provider" text NOT NULL,"providerOrderId" text UNIQUE,"providerPaymentId" text UNIQUE,"providerSignature" text,"amountPaise" integer NOT NULL,"currency" text NOT NULL,"status" "PaymentStatus" NOT NULL DEFAULT 'CREATING',"paymentSignatureVerified" boolean NOT NULL DEFAULT false,"webhookVerified" boolean NOT NULL DEFAULT false,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "Receipt" ("id" text PRIMARY KEY,"sessionId" text NOT NULL REFERENCES "ShoppingSession"("id") ON DELETE CASCADE,"kind" text NOT NULL,"receiptJson" jsonb NOT NULL,"receiptHash" text NOT NULL,"receiptSignature" text NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "AuditEvent" ("id" text PRIMARY KEY,"sessionId" text NOT NULL REFERENCES "ShoppingSession"("id") ON DELETE CASCADE,"actor" text NOT NULL,"eventType" text NOT NULL,"metadataJson" jsonb,"createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "WebhookEvent" ("id" text PRIMARY KEY,"provider" text NOT NULL,"providerEventId" text NOT NULL UNIQUE,"eventType" text NOT NULL,"payloadHash" text NOT NULL,"processed" boolean NOT NULL DEFAULT false,"processedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now());
